// Generated from the rule columns of the AFNOR XP Z12-012 V1.4 matrix. Rule texts are the French originals.
export const BUSINESS_RULES: BusinessRule[] = [
  { id: "BR-FR-01", family: 'br', title: "ID de facture 35 Caractères", text: "L'identifiant de facture DOIT ÊTRE limité à 35 caractères", bts: ["BT-1", "BT-25", "EXT-FR-FE-136"] },
  { id: "BR-FR-02", family: 'br', title: "ID de facture caractères autorisés", text: "L'Identifiant de facture (BT-1) est composé de caractères alphanumériques (A-Z, a-z, 0-9). Les caractères spéciaux suivants sont autorisés :\n- tiret (\"-\")\n- signe \"+\"\n- tiret bas (underscore : \"_\")\n- barre oblique (slash : \"/\")", bts: ["BT-1", "BT-25", "EXT-FR-FE-136"] },
  { id: "BR-FR-03", family: 'br', title: "Date entre 2000 et 2099", text: "L'année d'une date DOIT ETRE comprise entre 2000 et 2099", bts: ["BT-2", "BT-9", "BT-26", "BT-72", "BT-73", "BT-74", "BT-135", "EXT-FR-FE-138", "EXT-FR-FE-158"] },
  { id: "BR-FR-04", family: 'br', title: "Codes types documents", text: "Les codes types de documents pour une facture sont les suivants:\nFactures simples :\n- Facture commerciale (380)\n- Facture auto-facturée (389)\n- Facture affacturée (393)\n- Facture auto-facturée affacturée (501)\n\nFactures d'acompte :\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturée (500)\n\nFactures rectificatives :\n- Facture rectificative (384)\n- Facture rectificative auto-facturée ( 471)\n- Facture rectificative affacturée (472)\n- Facture rectificative auto-facturée affacturée ( 473)\n\nAvoirs :\n- Avoir auto-facturé (261)\n- Avoir pour Remise Globale (262)\n- Avoir (381)\n- Avoir affacturé (396)\n- Avoir auto-facturé affacturé (502)\n- Avoir de facture d'acompte (503)\n\nLes autres types de factures définis dans la norme (UNTDID 1001) ne doivent pas être utilisés.", bts: ["BT-3", "EXT-FR-FE-02", "EXT-FR-FE-137"] },
  { id: "BR-FR-05", family: 'br', title: "Note", text: "Toute facture DOIT comporter au moins 3 notes (BG-1) avec les codes suivants :\n- BT-21 = PMT, pour la mention de pénalité de 40 EUROS forfaitaire pour frais de recouvrement (en BT-22)\n- BT-21 = PMD, Mention de pénalités qui correspond aux conditions de paiement propres à chaque entreprise (en BT-22).\n- BT21 = AAB, mention d'escompte ou d'absence d'escompte (en BT-22)", bts: ["BG-1", "BT-21", "BT-22"] },
  { id: "BR-FR-06", family: 'br', title: "Note", text: "Parmi les notes (BG-3), les codes sujets (BT-21) PMD, PMT, AAB et TXD ne DOIVENT être présents qu'UNE SEULE FOIS CHACUN", bts: ["BG-1", "BT-21", "BT-22"] },
  { id: "BR-FR-08", family: 'br', title: "Cadre de facturation", text: "Le Cadre de facturation (BT-23) est obligatoire et les valeurs autorisées pour le Cadre de Facturation (BT-23) sont:\nB1 : Dépôt d'une facture de bien\nS1 : Dépôt d'une facture de prestation de service\nM1 : Dépôt d'une facture double (livraison de biens et services qui ne sont pas accessoires l'une de l'autre)\nB2 : Dépôt d'une facture de bien déjà payée\nS2 : Dépôt d'une facture de prestation de service déjà payée\nM2 : Dépôt d'une facture double déjà payée\nS3 : Dépôt d'une demande de paiement de sous-traitance avec paiement direct (uniquement B2G, restriction non vérifiable)\nB4 : Dépôt d'une facture définitive (après acompte) de bien\nS4 : Dépôt d'une facture définitive (après acompte) de service\nM4 : Dépôt d'une facture définitive (après acompte) double\nS5 : Dépôt par un sous-traitant d’une facture de prestation de service\nS6 : Dépôt par un cotraitant d’une facture de prestation de service\nB7 : Dépôt d'une facture de bien ayant fait l'objet d'un e-reporting (TVA déjà collectée)\nS7 : Dépôt d'une facture de prestation de service ayant fait l'objet d'un e-reporting (TVA déjà collectée)\nB8 : Dépôt d'une facture multi-vendeurs de biens\nS8 : Dépôt d'une facture multi-vendeurs de services\nM8 : Dépôt d'une facture multi-vendeurs double, contenant des factures unitaires qui ne sont pas toutes Sx ou Bx.\nB9 : Dépôt d'une facture bidirectionnelle de biens\nS9 : Dépôt d'une facture bidirectionnelle de services\nM9 : Dépôt d'une facture bidirectionnelle double", bts: ["BT-23"] },
  { id: "BR-FR-09", family: 'br', title: "Cohérence SIRET SIREN", text: "Dans une Partie, si le SIRET est renseigné (ID Privé, 0009), Les 9 premiers chiffres du SIRET doivent correspondre au SIREN renseigné en ID légal (schemeID 0002) et le SIRET doit faire 14 chiffres", bts: ["BT-29", "BT-29-1", "BT-29b", "BT-29b-1", "BT-46", "BT-46-1", "BT-46b", "BT-46b-1", "BT-60", "BT-60-1", "EXT-FR-FE-06", "EXT-FR-FE-07", "EXT-FR-FE-46", "EXT-FR-FE-47", "EXT-FR-FE-69", "EXT-FR-FE-70", "EXT-FR-FE-92", "EXT-FR-FE-92-1", "EXT-FR-FE-115", "EXT-FR-FE-116"] },
  { id: "BR-FR-10", family: 'br', title: "Gestion du SIREN", text: "Le SIREN du Vendeur est Obligatoire, et doit être présent et actif dans l'annuaire PPF", bts: ["BT-30"] },
  { id: "BR-FR-11", family: 'br', title: "Gestion du SIREN", text: "Pour les factures relevant du périmètre \"e-invoicing\", le SIREN de l'Acheteur est Obligatoire, et DOIT être présent et actif dans l'annuaire PPF\n\nRègle à exécuter si la facture fait l'objet d'un traitement B2B ou si elle contient une note (BG-1) avec un code sujet (BT-21) = BAR et un contenu (BT-22) = B2B :\n\nL'identifiant légal de l'Acheteur (BT-47) DOIT être présent.", bts: ["BT-47"] },
  { id: "BR-FR-12", family: 'br', title: "Adresse électronique de l'acheteur", text: "Dès lors que la facture électronique doit être transmise et attend des statuts de cycle de vie en retour, l'adresse électronique de l'Acheteur (BT-49) est OBLIGATOIRE. C'est l'adresse électronique à laquelle la facture est transmise (hors autofactures), ainsi que les statuts de cycle de vie à destination de l'ACHETEUR.\n\nPour information (géré par d'autres règles) : \nPour les factures hors autofacturation relevant du périmètre \"e-invoicing\", cette adresse électronique DOIT être de la forme \"SIREN\" ou \"SIREN_XXX\", le SIREN étant celui de l'Acheteur renseigné en BT-47, avec un schemeId (BT-49-1) = 0225.\n\nPour les factures hors périmètre \"e-invoicing\" ou dans le périmètre \"e-invoicing\" en autofacturation émises par l'Acheteur, l'adresse électronique de l'Acheteur DOIT être dans un des schemesID de la liste de codes EAS (y compris un email, avec schemeID (BT-49-1) = EM).\n\nPour les factures mises à disposition sur un portail, une adresse email (schemeID (BT-49-1) = EM) de type \"noreply@domaineduvendeur\" peut être utilisée pour signifier l'absence d'adresse électronique de l'Acheteur.", bts: ["BT-49", "BT-49-1"] },
  { id: "BR-FR-13", family: 'br', title: "Adresse électronique du Vendeur", text: "Dès lors que la facture électronique doit être transmise et attend des statuts de cycle de vie en retour, l'adresse électronique du Vendeur (BT-34) est OBLIGATOIRE. C'est l'adresse électronique à laquelle la facture en autofacturation est transmise, ainsi que les statuts de cycle de vie à destination du Vendeur.\n\nPour information (géré par d'autres règles) : \nPour les factures en autofacturation relevant du périmètre \"e-invoicing\", cette adresse électronique DOIT être de la forme \"SIREN\" ou \"SIREN_XXX\", le SIREN étant celui du Vendeur renseigné en BT-30, avec un schemeId (BT-34-1) = 0225.\n\nPour les factures hors périmètre \"e-invoicing\" ou dans le périmètre \"e-invoicing\" mais pas en autofacturation, l'adresse électronique du Vendeur DOIT être dans un des schemesID de la liste de codes EAS (y compris un email, avec schemeID (BT-34-1) = EM).\n\nPour les factures mises à disposition sur un portail, une adresse email de type \"noreply@domaineduvendeur\" peut être utilisée pour signifier l'absence d'adresse électronique du Vendeur.", bts: ["BT-34", "BT-34-1", "EXT-FR-FE-170", "EXT-FR-FE-170-1"] },
  { id: "BR-FR-15", family: 'br', title: "Code Catégorie de TVA", text: "Seuls les codes de catégorie de TVA suivants seront acceptés :\nS = Taux de TVA standard\nE = Exonéré de TVA\nAE = Autoliquidation de TVA\nK = Exonération pour cause de livraison intracommunautaire\nG = Exonération de TVA pour Export hors UE\nO = Hors du périmètre d'application de la TVA\nZ = Taux de TVA égal à 0 (cf. G1.47)\n\nLes codes de catégorie de TVA suivants ne sont pas pertinents en France :\nL = Iles Canaries\nM = Ceuta et Mellila", bts: ["BT-95", "BT-102", "BT-118", "BT-151"] },
  { id: "BR-FR-16", family: 'br', title: "Taux de TVA autorisé", text: "Le taux de la TVA applicable est conforme à la liste suivante :\nTaux\n0, 0.0, 0.00\n10, 10.0, 10.00\n13, 13.0, 13.00\n20, 20.0, 20.00\n8.5, 8.50\n19.6, 19.60\n2.1, 2.10\n5.5, 5.50\n7, 7.0, 7.00\n20.6, 20.60\n1.05\n0.9, 0.90\n1.75\n9.2, 9.20\n9.6, 9.60\n\nLe taux est exprimé en pourcentage et non en coefficient (exemple : 20). Le symbole « % » n’est pas à indiquer.\nLe séparateur (« . ») n'est pas comptabilisé dans les 5 caractères.", bts: ["BT-96", "BT-103", "BT-119", "BT-152"] },
  { id: "BR-FR-17", family: 'br', title: "Document Justificatif", text: "Pour qualifier les Pièces jointes, les codes suivants peuvent être utilisés :\nRIB : pour un RIB (qui contient l'IBAN / N° de compte + nom de Titulaire)\nLISIBLE : pour LA REPRÉSENTATION LISIBLE COMPLÈTE DE LA FACTURE.\nFEUILLE_DE_STYLE : pour le feuille de style permettant de créer une représentation lisible\nPJA : pour une pièce jointe additionnelle\nBORDEREAU_SUIVI : pour un bordereau de suivi\nDOCUMENT_ANNEXE : pour un document annexe\nBON_LIVRAISON :  un bon de livraison\nBON_COMMANDE: pour un Bon de Commande\nBORDEREAU_SUIVI_VALIDATION : pour un bordereau de suivi et validation\nETAT_ACOMPTE : pour un Etat d'acompte\nFACTURE_PAIEMENT_DIRECT : pour une facture de sous-traitant à payer en direct\nRECAPITULATIF_COTRAITANCE : pour lister l'ensemble des factures de co-traitance à traiter ensemble.", bts: ["BT-123"] },
  { id: "BR-FR-18", family: 'br', title: "Document Justificatif", text: "Il ne peut pas y avoir deux Documents additionnels (BG-24) pour lesquels la description BT-123 est égale à LISIBLE", bts: ["BT-123"] },
  { id: "BR-FR-20", family: 'br', title: "Qualification du type de traitement attendu", text: "Qualification du traitement attendu : Il est possible d'utiliser une Note pour indiquer quel traitement est attendu sur la facture. Le code sujet DOIT être BAR et les valeurs attendues, pour être signifiantes, DOIVENT être dans la liste ci-dessous, avec leurs significations :\n. B2B : signifie \"relève du e-invoicing\"\n. B2BINT : signifie \"relève du e-reporting des ventes B2Bint\"\n. B2C : signifie \"relève du e-reporting B2C Ventes\"\n. OUTOFSCOPE : signifie \"hors réforme\"\n. ARCHIVEONLY : signifie qu'il s'agit d'un AVOIR interne créé pour annuler une facture REJETÉE ou REFUSÉE, et NE DOIT PAS faire l'objet d'un traitement e-invoicing (pas de flux 1, pas de transmission au destinataire)", bts: ["BG-1", "BT-21", "BT-22"] },
  { id: "BR-FR-21", family: 'br', title: "Adresse électronique de l'acheteur", text: "Règle à exécuter si la facture fait l'objet d'un traitement B2B ou si elle contient une note (BG-1) avec un code sujet (BT-21) = BAR et un contenu (BT-22) = B2B :\n\nSi la facture n'est pas autofacturée (BT-3) pas dans liste ('389', '501', '500', '471', '473', '261', '502')\n\nALORS l'adresse de facturation électronique de l'ACHETEUR (BT-49) doit commencer par le N° SIREN de l'ACHETEUR (BT-47) ET le schemeID de l'adresse (BT-49-1) DOIT être égal à 0225", bts: ["BT-49", "BT-49-1"] },
  { id: "BR-FR-22", family: 'br', title: "Adresse électronique du Vendeur", text: "Règle à exécuter si la facture fait l'objet d'un traitement B2B ou si elle contient une note (BG-1) avec un code sujet (BT-21) = BAR et un contenu (BT-22) = B2B :\n\nSi la facture est autofacturée (BT-3 dans liste ('389', '501', '500', '471', '473', '261', '502')\n\nALORS l'adresse de facturation électronique du VENDEUR (BT-34) doit commencer par le N° SIREN du VENDEUR (BT-30) ET le schemeID de l'adresse (BT-34-1) DOIT être égal à 0225", bts: ["BT-34", "BT-34-1", "EXT-FR-FE-170", "EXT-FR-FE-170-1"] },
  { id: "BR-FR-23", family: 'br', title: "Adresse électronique en 0225", text: "Toute adresse électronique avec schemeID = 0225 est composé de caractères alphanumériques (A-Z, a-z, 0-9). Les caractères spéciaux suivants sont autorisés :\n- tiret (\"-\")\n- tiret bas (underscore : \"_\")\n- point (\".\")", bts: ["BT-34", "BT-34-1", "BT-49", "BT-49-1", "EXT-FR-FE-12", "EXT-FR-FE-13", "EXT-FR-FE-29", "EXT-FR-FE-30", "EXT-FR-FE-52", "EXT-FR-FE-53", "EXT-FR-FE-75", "EXT-FR-FE-76", "EXT-FR-FE-98", "EXT-FR-FE-99", "EXT-FR-FE-121", "EXT-FR-FE-122", "EXT-FR-FE-170", "EXT-FR-FE-170-1"] },
  { id: "BR-FR-24", family: 'br', title: "Code_Routage", text: "Toute IDprivé d'une partie avec schemeID = 0224 est composé de caractères alphanumériques (A-Z, a-z, 0-9). Les caractères spéciaux suivants sont autorisés :\n- tiret (\"-\")\n- tiret bas (underscore : \"_\")\n- pont (\".\")", bts: ["BT-29", "BT-29-1", "BT-29c", "BT-29c-1", "BT-46", "BT-46-1", "BT-46c", "BT-46c-1"] },
  { id: "BR-FR-25", family: 'br', title: "Adresse électronique", text: "Toute adresse électronique ne doit pas dépasser 125 caractères", bts: ["BT-34", "BT-34-1", "BT-49", "BT-49-1", "EXT-FR-FE-12", "EXT-FR-FE-13", "EXT-FR-FE-29", "EXT-FR-FE-30", "EXT-FR-FE-52", "EXT-FR-FE-53", "EXT-FR-FE-75", "EXT-FR-FE-76", "EXT-FR-FE-98", "EXT-FR-FE-99", "EXT-FR-FE-121", "EXT-FR-FE-122", "EXT-FR-FE-170", "EXT-FR-FE-170-1"] },
  { id: "BR-FR-26", family: 'br', title: "Code_Routage", text: "Toute IDprivé d'une partie avec schemeID = 0224 ne doit pas dépasser 100 caractères", bts: ["BT-29", "BT-29-1", "BT-29c", "BT-29c-1", "BT-46", "BT-46-1", "BT-46c", "BT-46c-1"] },
  { id: "BR-FR-27", family: 'br', title: "Code et Nom d'attribut d'article", text: "Un groupe Attribut d'article (BG-32) DOIT contenir soit un nom d'attribut d'article (BT-160), soit un Code d'attribut d'article (EXT-FR-FE-159)", bts: ["BT-160", "EXT-FR-FE-159"] },
  { id: "BR-FR-28", family: 'br', title: "Valeur d'attribut et Valeur d'attribut avec unité de mesure", text: "Un groupe Attribut d'article (BG-32) DOIT contenir soit une valeur d'attribut (BT-161), soit une valeur d'attribut avec unité de mesure (EXT-FR-FE-160), et son unité de mesure (EXT-FR-FE-161), et pas les deux.", bts: ["BT-161", "EXT-FR-FE-160", "EXT-FR-FE-161"] },
  { id: "BR-FR-29", family: 'br', title: "Identifiant d'objet facturé", text: "Parmi Identifiants d'Objets facturés (BT-18), les schémas d'identification (BT-18-1) \"AFL\" et \"AVV\" ne DOIVENT être présents qu'UNE SEULE FOIS CHACUN", bts: ["BT-18", "BT-128"] },
  { id: "BR-FR-30", family: 'br', title: "Identifiant d'objet facturé à la ligne", text: "Parmi Identifiants d'Objets facturés à la ligne (BT-128), les schémas d'identification (BT-128-1) \"AFL\" et \"AVV\" ne DOIVENT être présents qu'UNE SEULE FOIS CHACUN", bts: ["BT-18", "BT-128"] },
  { id: "BR-FR-32", family: 'br', title: "Quand présent, le SIREN comporte 9 chiffres", text: "Tout identifiant d'une Partie avec schemeID = '0002' ou '0231' DOIT être composé de 9 chiffres.", bts: ["BT-29", "BT-29d", "BT-30", "BT-46", "BT-47", "BT-60", "BT-61", "EXT-FR-FE-06", "EXT-FR-FE-08", "EXT-FR-FE-46", "EXT-FR-FE-48", "EXT-FR-FE-69", "EXT-FR-FE-71", "EXT-FR-FE-92", "EXT-FR-FE-94", "EXT-FR-FE-115", "EXT-FR-FE-117", "EXT-FR-FE-166", "EXT-FR-FE-167"] },
  { id: "BR-FR-CO-01", family: 'co', title: "Pas d'antidatage dans l'avenir", text: "La date de facture (BT-2) DOIT ETRE antérieure ou égale à date d'application du contrôle de conformité\n\nRègle non présente dans le schématron car dépend d'une donnée externe (date de traitement)", bts: ["BT-2"] },
  { id: "BR-FR-CO-02", family: 'co', title: "Unicité de la facture", text: "L'identifiant unique de facture doit être composé des éléments suivants:\n- Numéro de facture (BT-1)\n- Année de production de la facture (Issue de la date d'émission de la facture (BT-2))\n- Identifiant légal du Vendeur : numéro SIREN (BT-30)\n\nL’unicité de la facture vise à éviter les erreurs de facturation (double facturation notamment). Une facture présentant des informations similaires cumulativement sur ces trois données par rapport à une facture précédemment envoyée fera l’objet d’un rejet par les plateformes.\nLe contrôle d’unicité est systématiquement bloquant.\n\nEn cas de mandat de facturation, le numéro de facture doit comporter une racine propre au mandataire pour éviter les doublons de facture avec celles de son mandant.\n\nLe numéro de facture doit respecter la règlementation du BOFIP suivante:\nBOI-TVA-DECLA-30-20-20-10 du 18/10/2023\nSection : A. La numérotation des factures", bts: ["BT-1", "BT-2", "BT-30"] },
  { id: "BR-FR-CO-03", family: 'co', title: "Codestypes documents", text: "Si le codetype de la facture (BT-3) est égal à 262 (Avoir Remise Globale), alors :\n- Le numéro de contrat (BT-12) DOIT être présent\n- La période de facturation (BG-14) DOIT être présente", bts: ["BG-3", "BT-12", "BT-25", "BT-26"] },
  { id: "BR-FR-CO-04", family: 'co', title: "Codestypes documents", text: "Si le codetype de la facture (BT-3) est dans la liste suivante :\n\nFactures rectificatives :\n- Facture rectificative (384)\n- Facture rectificative auto-facturée (471) (*)\n- Facture rectificative affacturée (472) (*)\n- Facture rectificative auto-facturée affacturée (473)  (*)\n\nAlors UNE ET UNE SEULE Référence à une facture antérieure (BT-25) DOIT être présente, ainsi que sa Date (BT-26)", bts: ["BG-3", "BT-25", "BT-26"] },
  { id: "BR-FR-CO-05", family: 'co', title: "Codestypes documents", text: "Si le codetype de la facture (BT-3) est dans la liste suivante :\n\nAvoirs :\n- Avoir auto-facturé (261)\n- Avoir (381)\n- Avoir affacturé (396)\n- Avoir auto-facturé affacturé (502) (*)\n- Avoir de facture d'acompte (503) (*)\n\nAlors AU MOINS une Référence à une facture antérieure (BT-25) DOIT être présente ainsi que sa Date (BT-26) OU BIEN une Référence à une facture antérieure en ligne (EXT-FR-FE-136) DOIT être présente DANS CHAQUE ligne (BG-25) où le « Sous-type de ligne de facture » (EXT-FR-FE-163 / BT-X-8) a la valeur \"DETAIL\" ou n'est pas spécifié, ainsi que sa date (EXT-FR-FE-138)", bts: ["BG-3", "BT-25", "BT-26", "EXT-FR-FE-136", "EXT-FR-FE-BG-06"] },
  { id: "BR-FR-CO-07", family: 'co', title: "Date de versement de l'acompte", text: "La Date d'échéance (BT-9), si présente, DOIT être postérieure ou égale à la Date de facture (BT-2),\nSAUF SI la facture est de type acompte (BT-3) :\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturé (500) (*)\n- Avoir de facture d'acompte (503) (*)\n\nOU SAUF SI le Cadre de facturation (BT-23) est égal à :\n- B2 : Dépôt d'une facture de bien déjà payée\n- S2 : Dépôt d'une facture de prestation de service déjà payée\n- M2 : Dépôt d'une facture double déjà payée", bts: ["BT-9"] },
  { id: "BR-FR-CO-08", family: 'co', title: "Cadre de facturation Facture définitive", text: "Si le cadre de facturation (BT-23) est :\n- B4 : Factures définitives (après acompte) de bien\n- S4 : Factures définitives (après acompte) de prestation de service\n- M4 : Factures définitives (après acompte) double\n\nALORS le type de facture ne peut pas être :\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturée (500)\n- Avoir de facture d'acompte (503)", bts: ["BT-3", "BT-23"] },
  { id: "BR-FR-CO-09", family: 'co', title: "Cadre de facturation Déjà payé", text: "Si le cadre de facturation (BT-23) est :\n- B2 : Dépôt d'une facture de bien déjà payée\n- S2 : Dépôt d'une facture de prestation de service déjà payée\n- M2 : Dépôt d'une facture double déjà payée\n\nALORS\n- Le montant déjà payé (BT-113) est égal Montant total de la Facture avec la TVA (BT-112)\n- le Net à payer (BT-115) est égal à 0\n- la Date d'échéance (BT-9) DOIT indiquer la date à laquelle la facture a été payée", bts: ["BT-9", "BT-23"] },
  { id: "BR-FR-CO-10", family: 'co', title: "ID privés des parties", text: "Lorsque les Identifiants privés des acteurs sont multiples (par exemple BT-29), ils doivent être qualifiés par un identifiant du schéma (BT-29-1), il ne peut y avoir 2 identifiants privés avec le même identifiant du schéma", bts: ["BT-29", "BT-29-1", "BT-29b", "BT-29b-1", "BT-29c", "BT-29c-1", "BT-29d", "BT-29d-1", "BT-46", "BT-46-1", "BT-46b", "BT-46b-1", "BT-46c", "BT-46c-1", "BT-60", "BT-60-1", "EXT-FR-FE-06", "EXT-FR-FE-07", "EXT-FR-FE-46", "EXT-FR-FE-47", "EXT-FR-FE-69", "EXT-FR-FE-70", "EXT-FR-FE-92", "EXT-FR-FE-92-1", "EXT-FR-FE-115", "EXT-FR-FE-116"] },
  { id: "BR-FR-CO-11", family: 'co', title: "ID privés des parties", text: "Les identifiants privés des parties permettent de fournir des identifiants spécifiques, qualifiés par l'identifiant du schema (codelist ICD). Ainsi :\n- un SIRET (identifiant du schema = 0009)\n- un CODE_ROUTAGE (identifiant du schema = 0224)\n- Le SIREN de l'assujetti unique du Vendeur (identifiant du schema : 0231), uniquement en BT-29", bts: ["BT-29", "BT-29-1", "BT-29b", "BT-29b-1", "BT-29c", "BT-29c-1", "BT-29d", "BT-29d-1", "BT-46", "BT-46-1", "BT-46b", "BT-46b-1", "BT-46c", "BT-46c-1", "BT-60", "BT-60-1", "EXT-FR-FE-06", "EXT-FR-FE-07", "EXT-FR-FE-46", "EXT-FR-FE-47", "EXT-FR-FE-69", "EXT-FR-FE-70", "EXT-FR-FE-92", "EXT-FR-FE-92-1", "EXT-FR-FE-115", "EXT-FR-FE-116"] },
  { id: "BR-FR-CO-12", family: 'co', title: "Montant de TVA en EURO", text: "Si la Devise de facture (BT-5) est différente de EUR, alors\n- la devise de comptabilité BT-6 DOIT être présente et égale à EUR\n- Le montant de TVA en devise de comptabilité (et donc en EURO BT-111 DOIT être présente, et BT-111-1 DOIT être égal à EUR", bts: ["BT-5", "BT-6", "BT-111-1"] },
  { id: "BR-FR-CO-13", family: 'co', title: "Assujetti Unique Vendeur", text: "S'il existe une occurrence de BT-29 avec un schéma d'identification BT-29-1 = 0231, alors le Vendeur est Membre d'un Assujetti Unique (AU), et le numéro de SIREN de l'Assujetti Unique en BT-29 avec le schéma d'identification (BT-29-1) = 0231 DOIT être présent dans l'Annuaire PPF", bts: ["BT-29", "BT-29-1", "BT-29d", "BT-29d-1"] },
  { id: "BR-FR-CO-14", family: 'co', title: "Assujetti Unique Vendeur", text: "S'il existe une occurrence de BT-29 avec un schéma d'identification BT-29-1 = 0231, alors le Vendeur est Membre d'un Assujetti Unique (AU), et un bloc BG-1 DOIT être présent avec pour Code sujet (BT-21) = \"TXD\" ET un texte de note (BT-22) = \"MEMBRE_ASSUJETTI_UNIQUE\".", bts: ["BT-29", "BT-29-1", "BT-29d", "BT-29d-1"] },
  { id: "BR-FR-CO-15", family: 'co', title: "Assujetti Unique Vendeur", text: "S'il existe une occurrence de BT-29 avec un schéma d'identification BT-29-1 = 0231, alors le Vendeur est Membre d'un Assujetti Unique (AU) et le Bloc du Représentant fiscal du Vendeur (BG-11) DOIT être présent et contient les informations de l'Assujetti Unique (et en particulier son n° de TVA en BT-63)", bts: ["BG-11", "BT-29", "BT-29-1", "BT-29d"] },
  { id: "BR-FR-MAP-01", family: 'map', title: "ID de facture caractères autorisés", text: "Pour la constitution du flux 1 ou 10.1, flux 6 pour le PPF, l'identifiant de facture est réduit à 20 caractères s'il en contient plus de 20, de la façon suivante :\n- Troncature à 19 caractères à droite\n- ajout d'un \"T\" à gauche pour signifier la troncature\nExemple : 987654321-123456782-F202500125 donne T23456782-F202500125", bts: ["BT-1", "BT-25", "EXT-FR-FE-136"] },
  { id: "BR-FR-MAP-02", family: 'map', title: "Codestypes documents", text: "Si le codetype de la facture (BT-3) est égal à 262 (Avoir pour Remise Globale), alors :\nPour le flux 1 :\n- le codetype de la facture (BT-3 = 262) DOIT être mappé en 381 dans le flux 1 (BT-3)\n- la référence de Contrat (BT-12) de la facture doit être mappée dans la Référence à une facture antérieure (BT-25) du Flux 1, et la Date de début de période de facturation (BT-73)  DOIT être mappée dans la Date de facture antérieure (BT-26).\n\nPour le flux 10.1 :\n- le codetype de la facture (BT-3 = 262) DOIT être mappé en 381 dans le flux 10.1 (TT-21)\n- la référence de Contrat (BT-12) de la facture DOIT être mappée dans la Référence à une facture antérieure (TT-30) et la Date de début de période de facturation (BT-73)  DOIT être mappée dans la Date de facture antérieure (TT-31)", bts: ["BT-3", "BT-12"] },
  { id: "BR-FR-MAP-03", family: 'map', title: "TVA sur les débits", text: "Il est rappelé que l'option de TVA sur les débits est générale et l'emporte sur l'ensemble des factures émises. En cas de prestations de services et d'option pour la TVA sur les débits, l'exigibilité de la TVA est due au moment de l'inscription de la somme correspondante au débit du compte « client ». En pratique, le débit coïncide le plus souvent avec la facturation. Il est souligné que l'option d'acquitter la taxe d'après les débits ne peut avoir pour effet de retarder l'exigibilité de la taxe.\n\nL'indication de l'exigibilité de la TVA pour les débits est indiquée en BT-8 avec les valeurs 5 en CII et 3 en UBL.\nBT-8 est obligatoire pour les factures de service dès lors que l'assujetti Vendeur a opté pour les débits.\nDans le flux 10.1 la valeur de BT-8 est mappée en TT-24", bts: ["BT-8", "EXT-FR-FE-180"], uncontrolled: true },
  { id: "BR-FR-MAP-04", family: 'map', title: "Note mapping", text: "Seules les notes (BG-3) avec les codes sujets (BT-21) égaux à AAB, BLU et TXD DOIVENT être transmises dans le Flux 1 ou le flux 10.1 (TT-26 = BT-21, TT-27 = BT-22).\n\nLes notes avec d’autres codes sujet peuvent être transmises, ou pas en flux 1 ou 10.1", bts: ["BG-1", "BT-21", "BT-22"] },
  { id: "BR-FR-MAP-05", family: 'map', title: "TVA en EURO dans le flux 10.1", text: "Si la Devise de facture (BT-5) est EUR, alors TT-52 est égal à BT-110, sinon, TT-52 est égal à BT-111", bts: ["BT-5", "BT-6", "BT-110", "BT-111", "EXT-FR-FE-181", "EXT-FR-FE-182"] },
  { id: "BR-FR-MAP-06", family: 'map', title: "Assujetti Unique Vendeur", text: "S'il existe une occurrence du bloc Note (BG-1) avec pour Code sujet (BT-21) = \"TXD\" ET un texte de note (BT-22) = \"MEMBRE_ASSUJETTI_UNIQUE\", alors il faut transcoder \"MEMBRE_ASSUJETTI_UNIQUE\" en \"Membre d'un assujetti unique\" dans la BT-22 du flux 1", bts: ["BG-1", "BT-21", "BT-22", "BT-29"] },
  { id: "BR-FR-MAP-07", family: 'map', title: "Assujetti Unique Vendeur", text: "S'il existe une occurrence du bloc Note (BG-1) avec pour Code sujet (BT-21) = \"TXD\" ET un texte de note (BT-22) = \"MEMBRE_ASSUJETTI_UNIQUE\", alors il faut transcoder \"MEMBRE_ASSUJETTI_UNIQUE\" en \"Membre d'un assujetti unique\" dans la TT-27 du flux 10.1", bts: ["BG-1", "BT-21", "BT-22", "BT-29"] },
  { id: "BR-FR-MAP-08", family: 'map', title: "Franchise en base", text: "Si une facture contient un bloc de détail TVA (BG-23) contenant un code Categorie BT-118 = \"E\" ET un code VATEX BT-121 = \"VATEX-FR-FRANCHISE\", ALORS\nl'action à opérer dans le flux 1 est la suivante : \n- transcoder la BT-118 en \"Z\"\n- supprimer VATEX BT-121 et la raison en texte BT-120, si présentes", bts: ["BT-118", "BT-120", "BT-121", "EXT-FR-FE-178", "EXT-FR-FE-179"] },
  { id: "BR-FR-MAP-09", family: 'map', title: "Franchise en base", text: "Si une facture contient un bloc de détail TVA (BG-23) contenant un code Categorie BT-118 = \"E\" ET un code VATEX BT-121 = \"VATEX-FR-FRANCHISE\", alors il faut transcoder la BT-118 en \"Z\" et ne pas transmettre le code VATEX BT-121, ni la raison en texte BT-120, si présente, dans le flux 10.1 (TT-56)", bts: ["BT-118", "BT-120", "BT-121", "EXT-FR-FE-178", "EXT-FR-FE-179"] },
  { id: "BR-FR-MAP-10", family: 'map', title: "Adresse de Livraison", text: "Si BT-80 est présent, il y a une Adresse de Livraison et il faut renseigner tous les champs présents du groupe Adresse de Livraison (BG-15) en flux 1 ou 10.1, et en cas d'absence de la Ligne 1 (BT-75), du Code postal (BT-78) ou Localité (BT-77), fournir la donnée \"-\" à la place.", bts: ["BG-15", "BT-75", "BT-77", "BT-78", "BT-80"] },
  { id: "BR-FR-MAP-11", family: 'map', title: "Adresse de Livraison", text: "Si EXT-FR-FE-157 est présent, il y a une Adresse de Livraison en ligne et il faut renseigner tous les champs présents du groupe Adresse de Livraison (EXT-FR-FE-BG-10) sauf l'identifiant global du lieu (EXT-FR-FE-146, EXT-FR-FE-148) en flux 1 ou 10.1, et en cas d'absence de la Ligne 1 (EXT-FR-FE-151), du Code postal (EXT-FR-FE-155) ou Localité (EXT-FR-FE-154), fournir la donnée \"-\" à la place.", bts: ["EXT-FR-FE-150", "EXT-FR-FE-151", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-157"] },
  { id: "BR-FR-MAP-12", family: 'map', title: "Taux de TVA autorisé", text: "Le taux de la TVA applicable doit être mappé vers les données suivantes :\nTaux\n0\n10\n13\n20\n8.5\n19.6\n2.1\n5.5\n7\n20.6\n1.05\n0.9\n1.75\n9.2\n9.6\n\nLe taux est exprimé en pourcentage et non en coefficient (exemple : 20). Le symbole « % » n’est pas à indiquer.\nLe séparateur (« . ») n'est pas comptabilisé dans les 5 caractères.", bts: ["BT-96", "BT-103", "BT-119", "BT-152"] },
  { id: "BR-FR-MAP-13", family: 'map', title: "Donnée Flux 1, 10.1 CIBLE", text: "Cette donnée n'est pas exigée au DEMARRAGE de la réforme dans les flux 1 et 10.1, mais en CIBLE (01/09/2027)", bts: ["BG-15", "BG-20", "BG-26", "BG-27", "BG-28", "BG-29", "BG-31", "BT-26", "BT-75", "BT-76", "BT-77", "BT-78", "BT-79", "BT-80", "BT-92", "BT-95", "BT-96", "BT-127", "BT-127-00", "BT-129", "BT-130", "BT-134", "BT-135", "BT-136", "BT-141", "BT-146", "BT-147", "BT-148", "BT-153", "BT-165", "EXT-FR-FE-138", "EXT-FR-FE-149", "EXT-FR-FE-150", "EXT-FR-FE-151", "EXT-FR-FE-152", "EXT-FR-FE-153", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-156", "EXT-FR-FE-157", "EXT-FR-FE-158", "EXT-FR-FE-183", "EXT-FR-FE-BG-06", "EXT-FR-FE-BG-10"] },
  { id: "BR-FR-MAP-14", family: 'map', title: "Code Pays", text: "Les Codes Pays adresses des parties attendues dans les flux 1 et 10 situées dans les DOM/COM dans les flux 1 et 10 de la façon suivante\n\nGuadeloupe (la) : si code pays = GP, alors remplacer par FR\nMartinique (la) : si code pays = MQ, alors remplacer par FR\nRéunion (La) : si code pays = RE, alors remplacer par FR\n\nGuyane française (la ) : si code pays = FR ET Code postal commence par 973, alors remplacer par GF\nMayotte : si code pays = FR ET Code postal commence par 976, alors remplacer par YT", bts: ["BT-40", "BT-55", "BT-80", "EXT-FR-FE-157"] },
  { id: "BR-FR-MAP-15", family: 'map', title: "MAPPING BT-24", text: "Pour le flux 1, BT-24 doit être égal à :\nurn.cpro.gouv.fr:1p0:einvoicingextract#Base pour le profil DEMARRAGE, sans les lignes\nurn.cpro.gouv.fr:1p0:einvoicingextract#Full pour le profil complet (CIBLE)", bts: ["BT-24"] },
  { id: "BR-FR-MAP-16", family: 'map', title: "Identifiant du Vendeur et de l'Acheteur en flux 10", text: "L'identifiant du Vendeur (TT-33) renseigné est défini par le qualifiant (TT-33-1) :\n- \"0002\" --> SIREN sur 9 caractères\n- \"0223\" --> UE_HORS_FRANCE (correspond à l'identifiant de TVA intracommunautaire) sur 18 caractères\n- \"0227\" --> HORS_UE (dont Wallis et Futuna) (correspond au code Pays et aux 16 premiers caractères de la raison sociale) sur 18 caractères\n- \"0228\" --> RIDET sur  9 ou 10 caractères\n- \"0229\" --> TAHITI sur  9 caractères\n\nL'identifiant de l'Acheteur (TT-37) renseigné est défini par le qualifiant (TT-37-1) :\n- \"0002\" --> SIREN sur 9 caractères\n- \"0223\" --> UE_HORS_FRANCE (correspond à l'identifiant de TVA intracommunautaire) sur 18 caractères\n- \"0227\" --> HORS_UE (dont Wallis et Futuna) (correspond au code Pays et aux 16 premiers caractères de la raison sociale) sur  18 caractères\n- \"0228\" --> RIDET sur  9 ou 10 caractères\n- \"0229\" --> TAHITI sur  9 caractères", bts: ["BT-30", "BT-31", "BT-47", "BT-48"] },
  { id: "BR-FR-MAP-17", family: 'map', title: "TRONQUER A 255 Caractères", text: "Si la longueur de la donnée fait plus de 255 caractères \nALORS pour la même donnée à reporter dans le flux 1 \nIl ne faut conserver que les 255 premiers caractères à gauche et supprimer au delà", bts: ["BT-75", "BT-76", "BT-77", "BT-79", "BT-153", "BT-165", "EXT-FR-FE-151", "EXT-FR-FE-152", "EXT-FR-FE-153", "EXT-FR-FE-154", "EXT-FR-FE-156"] },
  { id: "BR-FR-MAP-18", family: 'map', title: "TRONQUER A 1024 Caractères", text: "Si la longueur de la donnée fait plus de1024 caractères \nALORS pour la même donnée à reporter dans le flux 1 \nIl ne faut conserver que les 1024 premiers caractères à gauche et supprimer au-delà", bts: ["BT-22", "BT-120", "BT-127", "EXT-FR-FE-178"] },
  { id: "BR-FR-MAP-19", family: 'map', title: "TRONQUER A 10 Caractères", text: "Si la longueur de la donnée fait plus de 10 caractères \nALORS pour la même donnée à reporter dans le flux 1 \nIl ne faut conserver que les 10 premiers caractères à gauche et supprimer au delà", bts: ["BT-78", "EXT-FR-FE-155"] },
  { id: "BR-FR-MAP-20", family: 'map', title: "TRONQUER A 100 Caractères", text: "Si la longueur de la donnée fait plus de 100 caractères \nALORS pour la même donnée à reporter dans le flux 1 \nIl ne faut conserver que les 100 premiers caractères à gauche et supprimer au delà", bts: ["EXT-FR-FE-149"] },
  { id: "BR-FR-MAP-21", family: 'map', title: "Prix Brut", text: "En cas d'absence du Prix Unitaire Brut (BT-148) dans la facture, \nALORS, pour la création du flux 1 :\nil faut indiquer le PU Net (BT-146) dans le PU Brut (BT-148)", bts: ["BT-148"] },
  { id: "BR-FR-MAP-22", family: 'map', title: "Prix Brut", text: "En cas d'absence du Prix Unitaire Brut (BT-148) dans la facture, \nALORS, pour la création du flux 10.1 :\nil faut indiquer le PU Net (BT-146) dans le PU Brut (TT-71)", bts: ["BT-148"] },
  { id: "BR-FR-MAP-23", family: 'map', title: "Format Date", text: "Dans le flux 10.0, les dates sont au format AAAMMJJ\nDONC, pour les flux 2, 8, et 9 sous syntaxe UBL, il faut supprimer les \"-\"\nEXEMPLE : 2025-02-12 devient 20250212", bts: ["BT-2", "BT-9", "BT-26", "BT-72", "BT-73", "BT-74", "BT-134", "BT-135", "EXT-FR-FE-138"] },
  { id: "BR-FR-MAP-24", family: 'map', title: "Exclusion des lignes GROUP et INFORMATION", text: "Seules les lignes (BG-25) sans sous-type de ligne (EXT-FR-FE-163) ou avec une valeur de sous-type de ligne égale à \"DETAIL\", DOIVENT être prises en compte pour la création des flux 1 ou flux 10.1.", bts: ["EXT-FR-FE-163"] },
  { id: "BR-FR-MAP-30", family: 'map', title: "Rabais sur Prix Unitaire", text: "En cas de multiplicité de rabais sur prix unitaire (BT-147), il faut en faire la somme pour renseigner le Flux 1 (BT-147) et le flux 10.1 (TT-70). Pour rappel, donnée obligatoire en flux 1 et 10.1 à compter de septembre 2027.", bts: ["BT-147"] },
  { id: "BR-FR-MAP-31", family: 'map', title: "Taux de TVA à 0 pour Factures hors scope (O)", text: "En cas de facture contenant des blocs de ventilation de TVA (BG-23) avec code Catégorie TVA hors scope (BT-118 = \"O\"), si le taux de TVA est absent (BT-119), il faut alors renseigner la valeur 0 en flux 1 (BT-119) et en flux 10.1 (TT-57)", bts: ["BT-119"] },
  { id: "BR-FR-DEC-01", family: 'dec', title: "Montant 19,2", text: "Le montant dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 2 décimales.\nLe séparateur entre le nombre entier et les décimales est un point (« . »).\nLe signe « - » devant le montant compte comme un caractère.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, le montant sera rejeté. Le séparateur (« . ») n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-92", "BT-93", "BT-99", "BT-100", "BT-106", "BT-107", "BT-108", "BT-109", "BT-110", "BT-111", "BT-112", "BT-113", "BT-114", "BT-115", "BT-116", "BT-117", "BT-131", "BT-136", "BT-137", "BT-141", "BT-142", "EXT-FR-FE-181", "EXT-FR-FE-182"] },
  { id: "BR-FR-DEC-02", family: 'dec', title: "Quantité 19,4", text: "La quantité facturée dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 4 décimales.\nLe séparateur entre le nombre entier et les décimales est un point (« . »).\nLe signe « - » devant le montant compte comme un caractère.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, le montant sera rejeté. Le séparateur (« . ») n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-129", "BT-149"] },
  { id: "BR-FR-DEC-03", family: 'dec', title: "Prix Unitaire 19,6", text: "Le montant dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 6 décimales.\nLe séparateur entre le nombre entier et les décimales est un point (« . »).\nIl n'y a pas de signe (toujours positif), sauf si le Cadre de facturation est égal à S9, M9 ou B9.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, le montant sera rejeté. Le séparateur (« . ») n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-146", "BT-147", "BT-148"] },
  { id: "BR-FR-DEC-04", family: 'dec', title: "Pourcentage Taux TVA 4.2", text: "Le taux de TVA dans une facture est exprimé par un nombre sur 4 positions, et ne peut comporter plus de 2 décimales.\nLe séparateur entre le nombre entier et les décimales est un point (« . »).\nIl n'y a pas de signe (toujours positif)\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 4 caractères, le montant sera rejeté. Le séparateur (« . ») n'est pas comptabilisé dans les 4 caractères.", bts: ["BT-96", "BT-103", "BT-119", "BT-152"] },
  { id: "BR-FR-MV-01", family: 'mv', title: "Facture multi-vendeurs — et bidirectionnelle (Cadre de Facturation 8 et 9)", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nToutes les lignes (BG-25) DOIVENT contenir un sous-type de ligne (EXT-FR-FE-163).", bts: ["EXT-FR-FE-163"] },
  { id: "BR-FR-MV-02", family: 'mv', title: "Facture multi-vendeurs — Ligne GROUP par sous-vendeur", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8 ou M8 alors :\n\nLa facture DOIT contenir au moins 1 ligne (BG-25) avec le sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162)", bts: ["EXT-FR-FE-163"] },
  { id: "BR-FR-MV-03", family: 'mv', title: "Facture multi-vendeurs — et bidirectionnelle", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8 ou M8, ou S9, B9, M9 alors :\n\nPour chaque ligne (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162), les données suivantes DOIVENT être présentes :\n. Un nom de vendeur à la ligne (EXT-FR-FE-164)\n. Un identifiant de vendeur à la ligne (EXT-FR-FE-167)\n. Un code pays de vendeur à la ligne (EXT-FR-FE-177)\n. Une valeur d'objet facturé (BT-128) avec identifiant de schema (BT-128-1) = AFL (numéro de facture par vendeur)\n. Une valeur d'objet facturé (BT-128) avec identifiant de schema (BT-128-1) = AVV (cadre de facturation par vendeur), différent de M8/S8/B8/M9/S9/B9\n. Un montant total avec TVA à la ligne (EXT-FR-FE-184) en devise de facture", bts: ["BT-128", "BT-128-1", "EXT-FR-FE-164", "EXT-FR-FE-167", "EXT-FR-FE-177"] },
  { id: "BR-FR-MV-05", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Règle de calcul du Total HT par Vendeur", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nLe total HT de ligne (BT-131) des lignes (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162) DOIT être égal à la somme des totaux de ligne (BT-131) des lignes pour lesquelles l'identifant de ligne Parent (EXT-FR-FE-162) est égal à l'identifiant de ligne (BT-126) de la ligne \"GROUP\".", bts: ["BT-128", "BT-128-1"] },
  { id: "BR-FR-MV-06", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Identifiant legal de Vendeur à la ligne", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nToutes les lignes de factures (BG-25) DOIVENT contenir un identifiant légal de vendeur à la ligne (EXT-FR-FE-167), identique à celui de la ligne (BG-25) dont l'identifiant de ligne (BT-126) est égal à l'identifiant de ligne Parent (EXT-FR-FE-162), si présent.", bts: ["EXT-FR-FE-167"] },
  { id: "BR-FR-MV-07", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — numéro de facture à la ligne", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nToutes les lignes de factures (BG-25) DOIVENT contenir un numéro de facture de ligne, codifié avec l'objet facturé (BT-128 avec BT-128-1 = AFL) identique à celui de la ligne (BG-25)  dont l'identifiant de ligne (BT-126) est égal à l'identifiant de ligne Parent (EXT-FR-FE-162), si présent.", bts: ["BT-128", "BT-128-1"] },
  { id: "BR-FR-MV-08", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — raison d'exemption à la ligne", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nToutes les lignes de factures (BG-25) DOIVENT contenir une raison d'exemption TVA en texte commençant par le numéro de facture en ligne (EXT-FR-FE-178) entre # (exemple #F2025003#)", bts: ["BT-128", "BT-128-1"] },
  { id: "BR-FR-MV-09", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Montant TVA par Vendeur de ligne \"GROUP\"", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nLe montant total TVA à la ligne (EXT-FR-FE-181) des lignes (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162) DOIT être égal à la somme des Montants de TVA de la ventilation de TVA (BT-117) pour lesquelles la raison d'exemption (BT-120) commence par le numero de facture à la ligne (BT-128 avec BT-128-1 = AFL) entre #", bts: ["EXT-FR-FE-181"] },
  { id: "BR-FR-MV-10", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Montant total avec TVA par Vendeur de ligne \"GROUP\"", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nSi le montant total avec TVA en ligne (EXT-FR-FE-184) d'une ligne (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162) est présent, alors :\n\nLa valeur absolue du (montant total avec TVA (EXT-FR-FE-184) - le montant HT total de ligne (BT-131) - le montant total de TVA de ligne (EXT-FR-FE-181)) <= 0,01 * nbre de sous-ligne avec sous-type de ligne (EXT-FR-FE-163) égal à \"DETAIL\".", bts: ["BT-131", "EXT-FR-FE-181"] },
  { id: "BR-FR-MV-11", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Numéro de factures de ligne pour le Vendeur principal", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nSi le Vendeur principal identifié dans le bloc Vendeur (BG-4) de la facture au travers de son identifiant légal (BT-30) dispose d'un groupe de lignes de facturation, alors il doit exister au moins une ligne (BG-25) avec sous-type de ligne (EXT-FR-FE-163) = \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162), pour laquelle le numéro de facture à la ligne (Valeur de BT-128 avec BT-128-1 = AFL) est égal au numéro de facture (BT-1).", bts: ["BT-128", "BT-128-1"] },
  { id: "BR-FR-MV-12", family: 'mv', title: "Facture multi-vendeurs — ou bidirectionnelle — Numéro de factures unitaires de ligne uniques", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8, M8, ou S9, B9, M9 alors :\n\nLes numéros de facture à la ligne (Valeur de BT-128 avec BT-128-1 = AFL) pour les lignes (BG-25) avec sous-type de ligne (EXT-FR-FE-163) = \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162) DOIVENT être uniques (une seule occurence), et DOIVENT :\n- être composés de caractères alphanumériques (A-Z, a-z, 0-9). Les caractères spéciaux suivants sont autorisés : tiret (\"-\"), signe \"+\", tiret bas (underscore) : \"_\", barre oblique (slash : \"/\")\n- et faire moins de 35 caractères.\n\nVoir recommandations pour créer des numéros de factures unitaires distincts et conformes aux exigences réglementaires, chapitre 4.4.12.2.", bts: ["BT-128", "BT-128-1"] },
  { id: "BR-FR-MV-13", family: 'mv', title: "Codes types des factures Multi Vendeur (pas d'auto-facture)", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8 ou M8 alors :\n\nle code type de facture (BT-3) est différent de :\n- Facture auto-facturée (389)\n- Avoir auto-facturé (261)\n- Facture auto-facturée affacturée (501)\n- Facture d’acompte auto-facturée (500)\n- Avoir auto-facturé affacturé (502)\n- Facture rectificative auto-facturée ( 471)\n- Facture rectificative auto-facturée affacturée ( 473)", bts: ["BT-3"] },
  { id: "BR-FR-MVMAP-01", family: 'mv', title: "facture unitaire par Vendeur en cas de facture multi-vendeurs", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8 ou M8 alors la Plateforme Agréée d'émission qui supporte la gestion des factures multi-vendeurs DOIT créer autant de flux 1 que de numéro de facture en ligne présents dans la facture. Pour ce faire, une première étape consiste à créer des factures unitaires par numéro de facture en ligne en suivant les règles ci-dessous sur la base des informations fournies dans la ligne (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162) :\n. Remplacer les informations du Vendeur (BG-4) par celles du Vendeur en ligne (EXT-FR-FE-BG-12)\n. Remplacer le numéro de facture (BT-1) par le numero de facture en ligne (BT-128, avec BT-128-1 = AFL)\n. Remplacer le Cadre de facturation (BT-23) par le cadre de facturation en ligne (BT-128 avec BT-128-1 = AVV).\n. Remplacer le code de date d'exigibilité TVA (option sur les débits, BT-8) par celui indiqué en ligne (EXT-FR-FE-180)\n. Remplacer le total TVA dans la devise de la facture (BT-110) par le montant TVA en devise de facture en ligne (EXT-FR-FE-181).\n. Si l'Identifiant de facture antérieure de la ligne \"GROUP\" (EXT-FR-FE-136) est présent le porter en Identifiant de facture antérieure (BT-25)\n. Si la date de facture antérieure de la ligne \"GROUP\" (EXT-FR-FE-138) est présent le porter en date de facture antérieure (BT-26)\n. Si présent, remplacer le total TVA dans la devise de comptabilisation (BT-111) par le montant TVA en devise de comptabilisation en ligne (EXT-FR-FE-182).\n. Remplacer le montant total avec TVA (BT-112), par le montant  total avec TVA en ligne (EXT-FR-FE-184).\n. Porter le montant déjà payé (BT-113) au montant total avec TVA ci-dessus.\n. Porter le montant Net à payer (BT-115) à 0 (par conséquent).\n. Conserver uniquement les lignes pour lesquelles le numéro de facture en ligne est celui la facture unitaire (BT-128, avec BT-128-1 = AFL).\n. Conserver uniquement les lignes de vendilation de TVA (BG-23) pour lesquelles la raison d'exemption en texte (BT-120) commence par le numéro de facture en ligne  (BT-128, avec BT-128-1 = AFL) entre #", bts: ["BT-128", "BT-128-1", "EXT-FR-FE-166", "EXT-FR-FE-166-1", "EXT-FR-FE-167", "EXT-FR-FE-167-1", "EXT-FR-FE-168", "EXT-FR-FE-168-1", "EXT-FR-FE-177", "EXT-FR-FE-178", "EXT-FR-FE-179", "EXT-FR-FE-180", "EXT-FR-FE-BG-12", "EXT-FR-FE-BG-13"] },
  { id: "BR-FR-MVMAP-02", family: 'mv', title: "Constitution du flux 1 ou 10.1", text: "Si le Cadre de facturation (BT-23) est égal à S8, B8 ou M8 alors la Plateforme Agréée d'émission qui supporte la gestion des factures multi-vendeurs DOIT créer autant de flux 1 que de factures unitaires (numéros de facture en ligne). \nPour ce faire, le seconde étape consiste à extraire le flux 1 ou 10.1 à partir de la facture unitaire, ce qui revient à utiliser les informations fournies dans la ligne (BG-25) avec un sous-type de ligne (EXT-FR-FE-163) égal à \"GROUP\" et sans identifiant de ligne Parent (EXT-FR-FE-162), identifiant les données spécifiques à chaque Vendeur, de la façon suivante :\n. Utiliser les informations du Vendeur en ligne (EXT-FR-FE-BG-12) au lieu de celles du Vendeur (BG-4)\n. Utiliser le numero de facture en ligne (BT-128, avec BT-128-1 = AFL) au lieu du numéro de facture (BT-1)\n. Utiliser le Cadre de facturation en ligne (BT-128 avec BT-128-1 = AVV) au lieu du Cadre de facturation (BT-23)\n. Utiliser le code de date d'exigibilité TVA (option sur les débits, EXT-FR-FE-180) au lieu de celui de la facture (BT-8)\n. Utiliser le total TVA dans la devise de la facture en ligne (EXT-FR-FE-181) au lieu de celui de la facture (BT-110), si présent\n. Si l'Identifiant de facture antérieure de la ligne \"GROUP\" (EXT-FR-FE-136) est présent, le porter en Identifiant de facture antérieure (BT-25) du flux 1 unitaire (TT-30 du flux 10.1)\n. Si la date de facture antérieure de la ligne \"GROUP\" (EXT-FR-FE-138) est présente, la porter en date de facture antérieure (BT-26) du flux 1 unitaire (TT-31 du flux 10.1)\n. Si présent, utiliser le total TVA dans la devise de la facture en ligne (EXT-FR-FE-182) au lieu de celui de la facture (BT-111).\n. Utiliser uniquement les lignes pour lesquelles pour lesquelles le numéro de facture en ligne est celui la facture unitaire (BT-128, avec BT-128-1 = AFL), et pour lesquelles le sous-type de ligne (EXT-FR-FE-163) est égal à \"DETAIL\".\n. Utiliser uniquement les lignes de vendilation de TVA (BG-23) pour lesquelles la raison d'exemption en texte (BT-120) commence par le numéro de facture en ligne  (BT-128, avec BT-128-1 = AFL) entre #", bts: ["BT-128", "BT-128-1", "EXT-FR-FE-166", "EXT-FR-FE-166-1", "EXT-FR-FE-167", "EXT-FR-FE-167-1", "EXT-FR-FE-168", "EXT-FR-FE-168-1", "EXT-FR-FE-177", "EXT-FR-FE-178", "EXT-FR-FE-179", "EXT-FR-FE-180", "EXT-FR-FE-BG-12", "EXT-FR-FE-BG-13"] },
  { id: "G1.01", family: 'ppf', title: "Types de facture autorisés", text: "Les types de factures autorisés sont: \nFactures simples :\n- Facture commerciale (380)\n- Facture auto-facturée (389)\n- Facture affacturée (393)\n- Facture auto-facturée affacturée (501) \n\nFactures d'acompte :\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturée (500)\n\nFactures rectificatives :\n- Facture rectificative (384)\n- Facture rectificative auto-facturée  (471)\n- Facture rectificative affacturée  (472)\n- Facture rectificative auto-facturée affacturée  (473)\nAvoirs : \n- Avoir auto-facturé (261)\n- Avoir (381)\n- Avoir affacturé (396)\n- Avoir auto-facturé affacturé (502)\n- Avoir de facture d'acompte (503) \n\nLes autres types de factures définis dans la norme (UNTDID 1001) ne doivent pas être utilisés.", bts: ["BT-3"] },
  { id: "G1.02", family: 'ppf', title: "Cadre de Facturation", text: "Les valeurs autorisées pour le Cadre (Mode de Facturation) sont:\nB1 : Dépôt d'une facture de bien\nS1 : Dépôt d'une facture de prestation de service\nM1 : Dépôt d'une facture double (livraison de bien et services qui ne sont pas accessoires l'une de l'autre)\nB2 : Dépôt d'une facture de bien déjà payée\nS2 : Dépôt d'une facture de prestation de service déjà payée\nM2 : Dépôt d'une facture double déjà payée\n\nB4 : Dépôt d'une facture définitive (après acompte) de bien\nS4 : Dépôt d'une facture définitive (après acompte) de service\nM4 : Dépôt d'une facture définitive (après acompte) double\nS5 : Dépôt par un sous-traitant d’une facture de prestation de service\nS6 : Dépôt par un cotraitant d’une facture de prestation de service\nB7 : Dépôt d'une facture de bien ayant fait l'objet d'un e-reporting (TVA déjà collectée)\nS7 : Dépôt d'une facture de prestation de service ayant fait l'objet d'un e-reporting (TVA déjà collectée)", bts: ["BT-23"] },
  { id: "G1.05", family: 'ppf', title: "Identifiant de la facture / identifiant de la facture d’origine", text: "L’identifiant de la facture est limité à  35 caractères alphanumériques.\nLes caractères spéciaux suivants sont autorisés :\n- espace (\" \")\n- tiret (\"-\")\n- signe \"+\"\n- tiret bas (underscore : \"_\")\n- barre oblique (slash : \"/\")\n\nL’identifiant ne doit pas comporter uniquement des espaces. L’identifiant ne peut pas débuter ou terminer par un espace et ne peut en outre comporter d’espaces consécutifs.", bts: ["BT-1", "BT-25", "EXT-FR-FE-136"] },
  { id: "G1.07", family: 'ppf', title: "Date d’émission de la facture", text: "La date de la facture, de transaction ou de paiement doit être antérieure ou égale à la date de contrôle dans le système.", bts: ["BT-2", "BT-26", "EXT-FR-FE-138"] },
  { id: "G1.09", family: 'ppf', title: "Date", text: "Tous les champs Date sont sous le format suivant :\nAAAA-MM-JJ en UBL\nAAAAMMJJ en CII\n\nDans le cadre du e-reporting (flux 10), le format des champs dates est obligatoirement : AAAAMMJJ. Conversion UBL vers CII.", bts: ["BT-2", "BT-9", "BT-26", "BT-72", "BT-73", "BT-74", "BT-134", "BT-135", "EXT-FR-FE-138", "EXT-FR-FE-158"] },
  { id: "G1.10", family: 'ppf', title: "Devise", text: "La liste des Valeurs autorisées pour la Devise d'une Facture est conforme à celle du référentiel ISO 4217", bts: ["BT-5", "BT-110-1", "BT-111-1"] },
  { id: "G1.12", family: 'ppf', title: "Gestion devise hors EUR", text: "Si BT-5 (Code de devise de la facture) est différent de l'Euro, alors la balise BT-111 (Montant total de TVA de la facture exprimée (devise de comptabilisation)) devient obligatoire et doit être exprimée en EURO", bts: ["BT-5"] },
  { id: "G1.14", family: 'ppf', title: "Format de montant", text: "Le montant dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 2 décimales. \nLe séparateur entre le nombre entier et les décimales est un point (« . »). \nLe signe « - » devant le montant compte comme un caractère.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, le montant sera rejeté. Le séparateur (« . ») n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-92", "BT-99", "BT-109", "BT-110", "BT-111", "BT-116", "BT-117", "BT-136", "BT-141"] },
  { id: "G1.15", family: 'ppf', title: "Format de quantité", text: "La quantité dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 4 décimales. \nLe séparateur entre le nombre entier et les décimales est un point (« . »). \nLe signe négatif (« - ») devant la quantité compte comme un caractère.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, la quantité sera rejetée. Le séparateur (« . ») n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-129"] },
  { id: "G1.16", family: 'ppf', title: "Format de prix", text: "Le prix dans une facture est exprimé par un nombre sur 19 positions, et ne peut comporter plus de 6 décimales. \nLe séparateur entre le nombre entier et les décimales est un point (« . »). \nAucun signe négatif devant le montant (« - ») n’est autorisé.\nSi le nombre total de chiffres du nombre (partie entière et partie décimale comprises) dépasse 19 caractères, le prix sera rejeté. Le séparateur (\".\") n'est pas comptabilisé dans les 19 caractères.", bts: ["BT-146", "BT-147", "BT-148"] },
  { id: "G1.18", family: 'ppf', title: "Date de versement de l'acompte", text: "Si le type de facture est:\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturé (500) (*),\nla date de versement de l’acompte doit être obligatoirement complétée  si la date de versement de l'acompte est déterminée / connue et qu'elle est différente de la date d'émission.\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-9"], uncontrolled: true },
  { id: "G1.24", family: 'ppf', title: "Taux de TVA autorisé", text: "Le taux de la TVA applicable est conforme à la liste suivante : \nTaux \n0\n10\n13\n20\n8.5\n19.6\n2.1\n5.5\n7\n20.6\n1.05\n0.9\n1.75\n9.2\n9.6\n\nLe taux est exprimé en pourcentage et non en coefficient (exemple : 20). Le symbole « % » n’est pas à indiquer.\nLe séparateur (« . ») n'est pas comptabilisé dans les  5 caractères.\n\nLe contrôle s’effectuera sur la valeur, sans tenir compte de la forme (par exemple : 20 ou 20.0 ou 20.00 seront considérés comme équivalents).", bts: ["BT-96", "BT-103", "BT-119"] },
  { id: "G1.31", family: 'ppf', title: "Référence facture antérieure en cas d'avoir ou facture rectificative", text: "En trajectoire de démarrage (profil BASE) \nle fichier de données réglementaires (F1) d’un avoir comporte obligatoirement les numéros de facture antérieure (BT-25) en entête de document et un unique numéro de facture antérieure dans le F1 d’une facture rectificative.\n \nEn trajectoire cible (profil FULL) \nla date (BT-26) liée à la facture antérieure devient aussi obligatoire. Il est attendu obligatoirement autant de dates qu’il existe de numéros de facture antérieure.\n \nil est possible de ne pas renseigner numéro de facture antérieure (BT-25) et date de facture antérieure (BT-26) en entête de document à la condition de les renseigner exclusivement sur chacune des lignes articles. Seuls les numéros (balise EXT-FR-FE-136) et dates (balise EXT-FR-FE-138) de facture antérieures sur chaque ligne article doivent obligatoirement être renseignées.\n \nSi ces informations (numéro/date de facture antérieure) sont renseignées à la fois en entête et sur les lignes de facture, le F1 d'avoir ou de facture rectificative sera rejetté.", bts: ["BG-3", "EXT-FR-FE-138", "EXT-FR-FE-BG-06"] },
  { id: "G1.32", family: 'ppf', title: "Référence facture antérieure en cas d'avoir ou facture rectificative", text: "Si la facture est de type \"Facture rectificative\" :\nAlors une et une seule Référence à une facture antérieure (TT-30) doit être présente, ainsi que sa Date (TT-31)\n\nSi la facture est de type \"Avoir\"  :  \nAlors au moins une Référence à une facture antérieure ainsi que sa Date doivent être présentes soit en entête (TT-30 et TT-31), soit dans chaque ligne de facture (TT-300 et TT-301).", bts: ["BG-3", "EXT-FR-FE-BG-06"] },
  { id: "G1.36", family: 'ppf', title: "Date", text: "Dans une date, l'année ne pourra pas être < 2000 et > 2099", bts: ["BT-2", "BT-9", "BT-26", "BT-72", "BT-73", "BT-74", "BT-134", "BT-135", "EXT-FR-FE-138", "EXT-FR-FE-158"] },
  { id: "G1.38", family: 'ppf', title: "Date effective de livraison / fin d'exécution de la prestation", text: "Donnée à fournir dans la mesure où elle est déterminée et différente de la date d'émission (art. 242 nonies A 10°). Dans une facture, peut être renseignée :\n- la date de livraison ou la date de fin d'exécution de la prestation (TT-41)\nou \n- une période de facturation en cas de facture périodique ou récapitulative (article 289 - I.3 du CGI) (TG-25)\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BG-26", "BT-72"], uncontrolled: true },
  { id: "G1.39", family: 'ppf', title: "Date effective de livraison / fin d'exécution de la prestation", text: "Donnée à fournir dans la mesure où elle est déterminée et différente de la date d'émission (art. 242 nonies A 10°). Dans une facture, peut être renseignée :\n- la date de livraison ou la date de fin d'exécution de la prestation (BT-72)\nou \n- la date de livraison à la ligne, en cas de multi-livraisons (EXT-FR-FE-BG-11)\nou \n- une période de facturation en cas de facture périodique ou récapitulative (article 289 - I.3 du CGI) (BG-26)\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BG-14", "BG-26", "BT-72"], uncontrolled: true },
  { id: "G1.40", family: 'ppf', title: "Motif d'exonération de TVA", text: "Une ventilation de la TVA (TG-23) avec le code de type de TVA (TT-56) « Exonération de TVA » (valeur \"E\") doit comprendre un code de motif d'exonération de la TVA (TT-59) et un motif d'exonération de la TVA (TT-58).", bts: ["BT-120", "BT-121", "EXT-FR-FE-178", "EXT-FR-FE-179"] },
  { id: "G1.41", family: 'ppf', title: "Motif d'exonération de TVA", text: "Une ventilation de la TVA (BG-23) avec le code de type de TVA (BT-118) « Exonération de TVA » (valeur \"E\") doit comprendre un code de motif d'exonération de la TVA (BT-121) et un motif d'exonération de la TVA (BT-120).\nCette règle ne s'applique pas en cas d'une facture rectificative ou d'une facture de moins de 150 € uniquement. En effet, dans ce cas précis, le code de motif d'exonération de la TVA (BT-121) et le motif d'exonération de la TVA (BT-120) peuvent être non renseignés.", bts: ["BT-120", "BT-121", "EXT-FR-FE-178", "EXT-FR-FE-179"] },
  { id: "G1.42", family: 'ppf', title: "Unicité de la facture", text: "Dans le cas d'une transmission déclarée par le vendeur, l'identifiant de facture, composé des éléments suivants:\n- Numéro de facture ( 35 caractères maximum) - (TT-19)\n- Année de production de la facture  (Issue de la date d'émission de la facture) - ( TT-20)\n- Identifiant du fournisseur : numéro SIREN  (TT-33).\ndoit être unique.\n\nL’unicité de la facture vise à éviter les erreurs de facturation (double facturation notamment). Une facture présentant un même identifiant de facture ( informations similaires cumulativement sur ces trois données) par rapport à une facture précédemment envoyée fera l’objet d’un rejet par les plateformes. \nLe contrôle d’unicité est systématiquement bloquant.\n\nEn cas de mandat de facturation, le numéro de facture doit comporter une racine propre au mandataire pour éviter les doublons de facture avec celles de son mandant.\n\nLe numéro de facture doit respecter la règlementation du BOFIP suivante:\nBOI-TVA-DECLA-30-20-20-10 du 18/10/2023\nSection : A. La numérotation des factures", bts: ["BT-1"] },
  { id: "G1.43", family: 'ppf', title: "Option de paiement de TVA", text: "L'option de TVA sur les débits est générale et l'emporte sur l'ensemble des factures émises. En cas de prestations de services et d'option pour la TVA sur les débits, l'exigibilité de la TVA est due au moment de l'inscription de la somme correspondante au débit du compte « client ». En pratique, le débit coïncide le plus souvent avec la facturation. Il est souligné que l'option d'acquitter la taxe d'après les débits ne peut avoir pour effet de retarder l'exigibilité de la taxe. L'option pour la TVA sur les débits est indiquée au travers du BT-8. Le BT-8 ne sera obligatoire que si l'entreprise a opté pour la TVA sur les débits et le spécifie au moyen du code 5 (CII) ou 3 (UBL).\n \nN.B. : Règle de gestion métier mais ne peut pas être contrôlée d'un point de vue applicatif", bts: ["BT-8", "EXT-FR-FE-180"], uncontrolled: true },
  { id: "G1.44", family: 'ppf', title: "Option de paiement de TVA", text: "L'option de TVA sur les débits est générale et l'emporte sur l'ensemble des factures émises. En cas de prestations de services et d'option pour la TVA sur les débits, l'exigibilité de la TVA est due au moment de l'inscription de la somme correspondante au débit du compte « client ». En pratique, le débit coïncide le plus souvent avec la facturation. Il est souligné que l'option d'acquitter la taxe d'après les débits ne peut avoir pour effet de retarder l'exigibilité de la taxe. L'option pour la TVA sur les débits est indiquée au travers du TT-24. Le TT-24 ne sera obligatoire que si l'entreprise a opté pour la TVA sur les débits et le spécifie au moyen du code 5 (CII) ou 3 (UBL)\n\nN.B. : Règle de gestion métier mais ne peut pas être contrôlée d'un point de vue applicatif", bts: ["BT-8", "EXT-FR-FE-180"], uncontrolled: true },
  { id: "G1.45", family: 'ppf', title: "Unicité de la facture", text: "L'identifiant de facture, composé des éléments suivants:\n- Numéro de facture ( 35 caractères maximum) - (BT-1 de la norme EN16931)\n- Année de production de la facture  (Issue de la date d'émission de la facture) - (BT-2 de la norme EN16931)\n- Identifiant du fournisseur : numéro SIREN (BT-30 de la norme EN16931).\ndoit être unique.\n\nL’unicité de la facture vise à éviter les erreurs de facturation (double facturation notamment). Une facture présentant un même identifiant de facture (informations similaires cumulativement sur ces trois données) par rapport à une facture précédemment envoyée fera l’objet d’un rejet par les plateformes. \nLe contrôle d’unicité est systématiquement bloquant (rejet des données de facturation (F1) correspondantes). Les données de facturation (F1) ayant fait l'objet d'un rejet du PPF (hors doublon) sont exclues de ce contrôle.\n\nEn cas de mandat de facturation, le numéro de facture doit comporter une racine propre au mandataire pour éviter les doublons de facture avec celles de son mandant.\n\nLe numéro de facture doit respecter la règlementation du BOFIP suivante:\nBOI-TVA-DECLA-30-20-20-10 du 18/10/2023\nSection : A. La numérotation des factures", bts: ["BT-1"] },
  { id: "G1.47", family: 'ppf', title: "Identifiant à la TVA du vendeur", text: "Si la facture contient dans la ventilation de TVA  le code \"E\" (Exonération) en BT-118, alors l'identifiant à la TVA du vendeur (BT-31) est obligatoire.\nLes entreprises en franchise en base ne disposant pas systématiquement d'un numéro de TVA pourront utiliser un code \"Z\" en  BT-118.", bts: ["BT-31", "BT-63"] },
  { id: "G1.52", family: 'ppf', title: "Code du sujet de la note de facture", text: "Valeur à choisir dans le référentiel de la norme UNTDID 4451, en particulier : \n\nAAB [Mention de l'escompte. Correspond aux conditions de paiement. Il s'agit d'une mention manuscrite indiquant au client qu'il peut appliquer un escompte s'il paie avant la date d'échéance du paiement. Cela ne correspond pas au montant de l'escompte.]\n\nTXD [Concerne les opérations externes à l’assujetti unique, c’est-à-dire les opérations entre un membre d’un assujetti unique et un tiers à cet assujetti unique.]\nLa note de facture (BT-22 ou TT-27) doit être obligatoirement: \"Membre d'un assujetti unique\"\n\nBLU [Peut servir aussi à d'autres taxes dont l'écotaxe.] \nLa note de facture (BT-22/BT-127 ou TT-27/TT-61-1) doit contenir \"Eco-participation (L. 541-10 du code de l'environnement)\" ou \"Eco-contribution DEEE\" pour l'écotaxe.\n\nN.B. : Règle de gestion métier mais ne peut pas être contrôlée d'un point de vue applicatif", bts: ["BT-21", "EXT-FR-FE-183"], uncontrolled: true },
  { id: "G1.53", family: 'ppf', title: "Cohérence montants de TVA", text: "Le montant total hors TVA des factures (TT-51) ou des transactions (TT-82) doit être égal à la somme des montants de base d'imposition du type de TVA (TT-54 / TT-87). Une tolérance de 1 centime sera possible pour éviter les problèmes d'arrondi. \nLe montant total de TVA des factures (TT-52) ou des transactions (TT-83) doit être égal à la somme des totaux de TVA par taux (TT-55 / TT-88)*. Une tolérance de 1 centime sera possible pour éviter les problèmes d'arrondi. \n\n*Applicable uniquement si la devise de la facture (TT-22) ou des transactions (TT-78) est l’EURO.", bts: ["BT-109", "BT-117"] },
  { id: "G1.55", family: 'ppf', title: "Cohérence du prix de l'article", text: "Si le prix brut de l’article (BT-148 ou TT-71) et le rabais sur le prix de l'article (BT-147 ou TT-70) sont renseignés alors le prix net de l'article (BT-146 pour le flux 1, TT-69 pour le flux 10) doit être égal au prix brut de l'article (BT-148 ou TT-71) - le rabais sur le prix de l'article (BT-147 ou TT-70)\nUne tolérance de 1 centime sera possible pour éviter les problèmes d'arrondi", bts: ["BT-146"] },
  { id: "G1.60", family: 'ppf', title: "Cadre de facturation (contrôle)", text: "Si le cadre de facturation est :\nB4 : Factures définitives (après acompte) de bien\nS4 : Factures définitives (après acompte) de prestation de service\nM4 : Factures définitives (après acompte) double\nalors le type de facture ne peut pas être :\n- Facture d'acompte (386)\n- Facture d’acompte auto-facturée (500)\n- Avoir de facture d'acompte (503)", bts: ["BT-3", "BT-23"] },
  { id: "G1.63", family: 'ppf', title: "Code SIREN AcheteurVendeur", text: "Le SIREN du vendeur (BT-30) et de l'acheteur (BT-47) sont obligatoires et doivent exister dans l’annuaire. L'identifiant de schéma associés à ces SIREN sont également obligatoires (les données règlementaires seront rejetées en cas d'absence).", bts: ["BT-30", "BT-47"] },
  { id: "G1.76", family: 'ppf', title: "Assujetti unique (en émission de facture)", text: "En cas d'assujetti unique, les données relatives au membre de l'assujetti unique doivent figurer dans le bloc VENDEUR (BG-4). \n\nEn sus, Il faut systématiquement renseigner les informations suivantes, les trois champs étant obligatoire :\n - La mention \"Membre d'un assujetti unique\" avec le code \"TXD\" dans la note de facture (cf. G1.52 ). \n - Les données relatives à l'assujetti unique, autres que le SIREN, doivent figurer dans le bloc REPRESENTANT FISCAL DU VENDEUR (BG-11).\n - Le champ BT-29d devra servir à renseigner le SIREN de l'assujetti unique", bts: ["BG-11", "BT-29d", "BT-63"] },
  { id: "G1.78", family: 'ppf', title: "N° TVA de l'Assujetti unique (en réception de facture)", text: "Le champ BT-48 sert à renseigner le numéro de TVA intracommunautaire de l'acheteur. \n\nEn cas d'appartenance à un assujetti unique, c'est le numéro de TVA intracommunautaire du membre de l'assujetti unique qui doit être renseigné dans ce champ. Le n° de TVAI de l'assujetti unique sera renseigné dans le bloc REPERESENTANT FISCAL DU VENDEUR (BG-11).\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-48"], uncontrolled: true },
  { id: "G1.79", family: 'ppf', title: "SIREN de l'Assujetti unique acheteur (en réception de facture)", text: "En cas d'assujetti unique, le SIREN de l'acheteur à renseigner est celui du membre de l'assujetti unique.\n\nN.B. : Règle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-47"], uncontrolled: true },
  { id: "G1.89", family: 'ppf', title: "Format du SIREN", text: "Le SIREN se compose de 9 chiffres", bts: ["BT-29d", "BT-30", "BT-47"] },
  { id: "G1.101", family: 'ppf', title: "Assujetti unique (contrôle)", text: "Le SIREN de l’assujetti unique doit exister dans l’annuaire, sinon les données règlementaires seront rejetées", bts: ["BT-29d"] },
  { id: "G1.102", family: 'ppf', title: "Identifiant à la TVA du vendeur", text: "Si la facture contient dans la ventilation de TVA  le code \"E\" (Exonération) en TT-56, alors l'identifiant à la TVA du vendeur (TT-34) ou l'identifiant à la TVA du représentant fiscal du vendeur (TT-122) est obligatoire.\nLes entreprises en franchise en base ne disposant pas systématiquement d'un numéro de TVA pourront utiliser un code Z en TT-56.", bts: ["BT-31", "BT-63"] },
  { id: "G2.01", family: 'ppf', title: "Code Pays", text: "Le code Pays doit exister dans le Code ISO 3166 (norme alpha-2 uniquement).", bts: ["BT-40", "BT-55", "BT-80", "EXT-FR-FE-157"] },
  { id: "G2.19", family: 'ppf', title: "Identifiant du Vendeur et de l'Acheteur", text: "L'identifiant du Vendeur (TT-33-1) renseigné est défini par le qualifiant (issu du référentiel ICD 6523) :\n- \"0002\" --> SIREN sur 9 caractères numériques\n- \"0223\" --> UE_HORS_FRANCE (correspond à l'identifiant de TVA intracommunautaire) sur 18 caractères maximum\n- \"0227\" --> HORS_UE (dont Wallis et Futuna) (correspond au code Pays et les 16 premiers caractères de la raison sociale) sur  18 caractères maximum\n- \"0228\" --> RIDET sur  9 ou 10 caractères\n- \"0229\" --> TAHITI sur  9 caractères\n\nL'identifiant de l'Acheteur (TT-37) renseigné est défini par le qualifiant (issu du référentiel ICD 6523) :\n- \"0002\" --> SIREN sur 9 caractères numériques\n- \"0223\" --> UE_HORS_FRANCE (correspond à l'identifiant de TVA intracommunautaire) sur 18 caractères maximum\n- \"0227\" --> HORS_UE (dont Wallis et Futuna) (correspond au code Pays et les 16 premiers caractères de la raison sociale) sur  18 caractères maximum\n- \"0228\" --> RIDET sur  9 ou 10 caractères\n- \"0229\" --> TAHITI sur  9 caractères", bts: ["BT-30-1", "BT-47-1"] },
  { id: "G2.31", family: 'ppf', title: "Code de catégorie de TVA", text: "Seuls les codes de catégorie de TVA suivants seront acceptés: \nS = Taux de TVA standard\nE = Exonéré de TVA\nAE = Autoliquidation de TVA\nK =  Exonération pour cause de livraison intracommunautaire\nG = Exonération de TVA pour Export hors UE\nO = Hors du périmètre d'application de la TVA\nZ = Taux de TVA égal à 0 (cf. G1.47)\n\nLes codes de catégorie de TVA suivants ne sont pas pertinents en France : \nL = Iles Canaries\nM = Ceuta et Mellila", bts: ["BT-95", "BT-102", "BT-118"] },
  { id: "G2.32", family: 'ppf', title: "Règle de TVA hors champs", text: "Les données de facturation (F1) seront rejetées si la facture comporte uniquement des codes de type TVA à « O » (Hors champs de la TVA) (BT-118)\net/ou\nuniquement des codes de type TVA à « E » (Exonéré) (BT-118), associés à des code d’exonération (BT-121) correspondant à l’un des codes ci-dessous :\n• VATEX-FR-CGI261-1\n• VATEX-FR-CGI261-2\n• VATEX-FR-CGI261-3\n• VATEX-FR-CGI261-4\n• VATEX-FR-CGI261-5\n• VATEX-FR-CGI261-7\n• VATEX-FR-CGI261-8\n• VATEX-FR-CGI261A\n• VATEX-FR-CGI261B\n• VATEX-FR-CGI261C-1\n• VATEX-FR-CGI261C-2\n• VATEX-FR-CGI261C-3\n• VATEX-FR-CGI261D-1\n• VATEX-FR-CGI261D-1BIS\n• VATEX-FR-CGI261D-2\n• VATEX-FR-CGI261D-3\n• VATEX-FR-CGI261D-4\n• VATEX-FR-CGI261E-1\n• VATEX-FR-CGI261E-2\n\nCette règle est applicable pour toutes les données de facturation (F1) issues de factures B2B, B2G, G2B.", bts: ["BT-118", "BT-121", "EXT-FR-FE-179"] },
  { id: "G2.33", family: 'ppf', title: "Identifiant à la TVA du Vendeur et de l'Acheteur", text: "Si l'identifiant du schéma de l'identifiant du Vendeur (TT-33-1) est égal à 0002 ou 0223 alors l'identifiant à la TVA du Vendeur (TT-34) doit être systématiquement complété et qualifié en TT-34-0 par la valeur \"VAT\"\n\nSi l'identifiant du schéma de l'identifiant de l'Acheteur (TT-37) est égal à 0002 ou 0223 alors l'identifiant à la TVA de l'Acheteur (TT-38)/ doit être systématiquement complété et qualifié en TT-38-0 par la valeur \"VAT\"", bts: ["BT-30-1", "BT-31", "BT-31-0", "BT-47-1", "BT-48", "BT-48-0"] },
  { id: "G6.06", family: 'ppf', title: "Gestion de la DEEE", text: "Note à la ligne permettant d'indiquer si la ligne concerne une DEEE\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BT-127"], uncontrolled: true },
  { id: "G6.07", family: 'ppf', title: "B2C", text: "Mention obligatoire de facture prévue par les textes (article 242 nonies A ann.II au CGI) qui n'est pas exigée dans le cadre du e-reporting B2C (art. 242 nonies M ann.II au CGI).", bts: ["BG-3", "BG-5", "BG-7", "BG-8", "BG-11", "BG-13", "BG-14", "BG-15", "BG-20", "BG-21", "BG-26", "BG-27", "BG-28", "BG-29", "BG-31", "BT-21", "BT-22", "BT-25", "BT-26", "BT-40", "BT-47-1", "BT-55", "BT-63", "BT-63-0", "BT-72", "BT-73", "BT-74", "BT-75", "BT-77", "BT-78", "BT-80", "BT-92", "BT-95", "BT-96", "BT-99", "BT-102", "BT-103", "BT-109", "BT-118", "BT-129", "BT-130", "BT-135", "BT-136", "BT-141", "BT-146", "BT-147", "BT-148", "BT-153", "EXT-FR-FE-136", "EXT-FR-FE-138", "EXT-FR-FE-149", "EXT-FR-FE-151", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-157", "EXT-FR-FE-BG-06"] },
  { id: "G6.08", family: 'ppf', title: "Données obligatoires - Trajectoire \"DEMARRAGE\"", text: "Cette donnée est systématiquement obligatoire à partir du 01/09/2026", bts: ["BG-4", "BG-5", "BG-7", "BG-8", "BG-22", "BG-23", "BT-1", "BT-2", "BT-3", "BT-5", "BT-23", "BT-24", "BT-30", "BT-30-1", "BT-40", "BT-47", "BT-47-1", "BT-55", "BT-109", "BT-110", "BT-110-1", "BT-116", "BT-117", "BT-118", "BT-119"] },
  { id: "G6.09", family: 'ppf', title: "Données obligatoires - Trajectoire \"CIBLE\"", text: "Cette donnée est systématiquement obligatoire à partir du 01/09/2027", bts: ["BG-29", "BG-31", "BT-129", "BT-130", "BT-146", "BT-148", "BT-153"] },
  { id: "G6.10", family: 'ppf', title: "Taux de TVA de la remise au niveau du document", text: "Si le bloc BG-20 (REMISES AU NIVEAU DU DOCUMENT) est renseigné et le code de type de TVA BT-95 est différent de \"Non soumis à la TVA\", alors le Taux de TVA de la remise au niveau du document (BT-96) est obligatoire.", bts: ["BT-96"] },
  { id: "G6.11", family: 'ppf', title: "Données obligatoires selon le cas de gestion - Trajectoire \"DEMARRAGE\"", text: "Cette donnée est obligatoire à partir du 01/09/2026 lorsque la donnée doit être mentionnée sur la facture conformément à la réglementation (CGI, Ccom,...).\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BG-1", "BG-3", "BG-11", "BG-13", "BG-14", "BT-8", "BT-9", "BT-21", "BT-22", "BT-25", "BT-29d", "BT-29d-1", "BT-31", "BT-31-0", "BT-48", "BT-48-0", "BT-63", "BT-63-0", "BT-72", "BT-73", "BT-74", "BT-111", "BT-111-1", "BT-120", "BT-121", "EXT-FR-FE-178", "EXT-FR-FE-179", "EXT-FR-FE-180"], uncontrolled: true },
  { id: "G6.12", family: 'ppf', title: "Données obligatoires selon le cas de gestion - Trajectoire \"CIBLE\"", text: "Cette donnée est obligatoire à partir du 01/09/2027 lorsque la donnée doit être mentionnée sur la facture conformément à la réglementation (CGI, Ccom,...).\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BG-15", "BG-20", "BG-26", "BG-27", "BG-28", "BT-26", "BT-75", "BT-76", "BT-77", "BT-78", "BT-79", "BT-80", "BT-92", "BT-95", "BT-96", "BT-127", "BT-127-00", "BT-134", "BT-135", "BT-136", "BT-141", "BT-147", "BT-165", "EXT-FR-FE-136", "EXT-FR-FE-138", "EXT-FR-FE-149", "EXT-FR-FE-150", "EXT-FR-FE-151", "EXT-FR-FE-152", "EXT-FR-FE-153", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-156", "EXT-FR-FE-157", "EXT-FR-FE-158", "EXT-FR-FE-183", "EXT-FR-FE-BG-06", "EXT-FR-FE-BG-10"], uncontrolled: true },
  { id: "G6.13", family: 'ppf', title: "Représentant fiscal du vendeur", text: "Le bloc BG-11 (Représentant fiscal du vendeur) doit être renseigné avec les données relatives à l'assujetti unique, si applicable (voir G1.76)\n \nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BG-11"], uncontrolled: true },
  { id: "G6.14", family: 'ppf', title: "Données obligatoires - Trajectoire \"DEMARRAGE\"", text: "Transaction B2B international : Cette donnée est obligatoire à partir du 01/09/2026 lorsque la donnée doit être mentionnée sur la facture conformément à la réglementation (CGI, Ccom,...).\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BG-11", "BG-13", "BG-14", "BT-9", "BT-21", "BT-22", "BT-25", "BT-31", "BT-48", "BT-72", "BT-73", "BT-74", "BT-120", "BT-121", "EXT-FR-FE-136", "EXT-FR-FE-178", "EXT-FR-FE-179"], uncontrolled: true },
  { id: "G6.15", family: 'ppf', title: "Données obligatoires - Trajectoire \"CIBLE\"", text: "Transaction B2B international : Cette donnée est obligatoire à partir du 01/09/2027 lorsque la donnée doit être mentionnée sur la facture conformément à la réglementation (CGI, Ccom,...).\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif.", bts: ["BG-20", "BG-21", "BG-26", "BG-27", "BG-28", "BT-26", "BT-127", "BT-127-00", "BT-135", "BT-147", "EXT-FR-FE-138", "EXT-FR-FE-149", "EXT-FR-FE-157", "EXT-FR-FE-183"], uncontrolled: true },
  { id: "G6.16", family: 'ppf', title: "Données obligatoires - Trajectoire \"CIBLE\" - Adresse de livraison", text: "Certaines données liées à l'adresse de livraison BG-15 sont obligatoires si l’adresse est différente de l'adresse de facturation (Acheteur - Bloc BG-8) et seulement à partir du 01/09/2027. Les données obligatoires sont les suivantes : \n•\tAdresse de livraison  - Ligne 1 (BT-75)\n•\tLocalité Adresse de livraison (BT-77)\n•\tCode postal Adresse de livraison (BT-78)\n•\tCode Pays Adresse de livraison (BT-80)\nCes informations peuvent également être transmises à la ligne ( (si différent entête) - Bloc EXT-FR-FE-BG-10 ).\n\nCes données ne sont pas à transmettre pour les prestations de service\n \nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-75", "BT-77", "BT-78", "BT-80", "EXT-FR-FE-149", "EXT-FR-FE-151", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-157", "EXT-FR-FE-BG-10"], uncontrolled: true },
  { id: "G6.20", family: 'ppf', title: "Date de fin d'une période de facturation", text: "La date de fin d’une période de facturation ne peut pas être antérieure à la date de début de période.", bts: ["BT-74"] },
  { id: "G6.21", family: 'ppf', title: "Exonération TVA - Avoir net de taxe", text: "Si, dans la facture, il y a un code de motif d'exonération de la TVA (BT-121 pour le flux 1, ou TT-59 pour le flux 10) égal à VATEX-FR-CNWVAT (avoir net de taxe), alors le type de document (BT-3 ou TT-21) doit être de type avoir (261 - Avoir auto-facturé, 381 – Avoir, 396 - Avoir affacturé).", bts: ["BT-121", "EXT-FR-FE-179"] },
  { id: "G6.25", family: 'ppf', title: "Date de fin d'une période de transmission", text: "La date de fin d’une période de transmission ne peut pas être antérieure ou égale à la date de début de période.", bts: ["BT-135"] },
  { id: "G6.30", family: 'ppf', title: "Données obligatoires - Trajectoire \"CIBLE\" - Adresse de livraison", text: "Certaines données liées à l'adresse de livraison TG-19 sont obligatoires si l’adresse est différente de l'adresse de facturation (Acheteur - Bloc TG-15) et seulement à partir du 01/09/2027. Les données obligatoires sont les suivantes :\n• Adresse de livraison - Ligne 1 (TT-103)\n• Localité Adresse de livraison (TT-106)\n• Code postal Adresse de livraison (TT-107)\n• Code de pays (TT-44)\nCes informations peuvent également être transmises à la ligne (bloc TG-41).\n\nCes données ne sont pas à transmettre pour les prestations de service\n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-75", "BT-77", "BT-78", "BT-80", "EXT-FR-FE-149", "EXT-FR-FE-151", "EXT-FR-FE-154", "EXT-FR-FE-155", "EXT-FR-FE-157", "EXT-FR-FE-BG-10"], uncontrolled: true },
  { id: "P1.11", family: 'ppf-other', title: "Option paiement TVA", text: "Le code doit être choisi dans la liste UNTDID 2475 Subset ou UNTDID 2005 Subset", bts: ["BT-8"] },
  { id: "P1.12", family: 'ppf-other', title: "Cadre de facturation (contrôle)", text: "La date d'échéance est parfois calculée automatiquement par les logiciels à partir de la date d'émission. \n\nRègle de gestion métier mais ne peut pas être contrôlée d’un point de vue applicatif", bts: ["BT-9"], uncontrolled: true },
  { id: "S1.06", family: 'ppf-other', title: "Liste des valeurs du type de profil (Flux 1 et CDV)", text: "Gestion du flux 1 :\n\nL'identification du profil du F1 est réalisée au niveau du nom du fichier F1 qui doit suivre la règle de nommage suivante :\n \nEn trajectoire de démarrage : Base_<nom_du_fichier> \nEn trajectoire de cible : Full_<nom_du_fichier>\n \nNB : Il est important de respecter la casse\n \nLa  valeur de la BT-24 du flux 1 peut être alimentée par la valeur de la BT-24 du flux 2\n\nGestion flux CDV :\n1. CDV sur un flux (e-invoicing, annuaire, CDV ou e-reporting)\nurn.cpro.gouv.fr:1p0:CDV:flux\n\n2. CDV sur une facture (e-invoicing) :\nurn.cpro.gouv.fr:1p0:CDV:einvoicingF2\n\n3. CDV sur des données réglementaires (e-invoicing) :\nurn.cpro.gouv.fr:1p0:CDV:einvoicingF1\n\n4. CDV sur une transmission (e-reporting) :\nurn.cpro.gouv.fr:1p0:CDV:ereportingF10\n\n6. CDV sur des données annuaires :\nurn.cpro.gouv.fr:1p0:CDV:annuaire\n\n7. CDV sur un statut (CDV de CDV) :\nurn.cpro.gouv.fr:1p0:CDV:messageCDV", bts: ["BT-24"] },
  { id: "S1.12", family: 'ppf-other', title: "Liste des valeurs du type de profil", text: "Pour le Flux de e-reporting\nurn.cpro.gouv.fr:1p0:ereporting", bts: ["BT-24"] },
  { id: "S1.14", family: 'ppf-other', title: "Qualifiant de l'assujetti unique", text: "Pour mentionner un assujetti unique, il faut utiliser le qualifiant 0231", bts: ["BT-29d"] },
  { id: "S1.16", family: 'ppf-other', title: "Total de TVA unique", text: "Si BT-5 (Devise) est exprimée en EUR, alors BT-110 (Montant total de TVA de la facture) doit être exprimée en EUR et BT-110-1 est égale à \"EUR\"). Par conséquent, la balise BT-111 (Montant total de TVA de la facture exprimée (devise de comptabilisation)) ne doit pas être renseignée.\n\nSi BT-5 (Devise) est exprimée dans une devise autre que EUR, alors BT-110 (Montant total de TVA de la facture) doit être exprimée dans la dite devise (BT-110-1 égale à BT-5) .\nPar conséquent, la balise BT-111 (Montant total de TVA de la facture exprimée (devise de comptabilisation)) doit obligatoirement être renseignée dans la devise EUR (BT-111-1  égale à \"EUR\").", bts: ["BT-5"] },
  { id: "S1.17", family: 'ppf-other', title: "Qualifiant Identifiant à la TVA", text: "Le qualifiant d'identifiant à la TVA est obligatoire, il doit avoir une valeur de qualifiant unique :\n-\tEn format UBL la valeur de qualifiant unique est « VAT » pour les balises BT-31-0, BT-48-0, BT-63-0, BT-95-0, BT-102-0, BT-118-0\n-\tEn format CII la valeur de qualifiant unique est \"VAT\" pour les balises BT-95-0, BT-102-0, BT-118-0 ou « VA » pour l’attribut @SchemeID des balises BT-31-0, BT-48-0, BT-63-0.", bts: ["BT-31-0", "BT-48-0", "BT-63-0", "BT-95-0", "BT-102-0", "BT-118-0"] },
]


